fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            let mut lines: Vec<String> = Vec::new();
            let mut current_line = String::new();
            let mut chars = s.chars().peekable();

            while let Some(c) = chars.next() {
                current_line.push(c);
                if c == '\n' || (keepends && c == '\r' && chars.peek() == Some(&'\n')) {
                    if keepends {
                        current_line.push(c);
                    }
                    lines.push(current_line);
                    current_line = String::new();
                }
            }

            // If there's any remaining content in current_line, add it as well
            if !current_line.is_empty() {
                lines.push(current_line);
            }

            // Ensure that we have at least one element in the inner list
            if lines.is_empty() {
                lines.push(String::new());
            }

            lines
        })
        .collect()
}